1: use std::{future::Future, pin::Pin, time::Duration};
2: pub type Receipt = u64;
3: pub type Delivery<'a> = Pin<Box<dyn Future<Output = Receipt> + Send + 'a>>;
4: pub trait Transport {
5:     fn send(&self, request: u64) -> Delivery<'_>;
6: }
7: #[derive(Debug, PartialEq, Eq)]
8: pub enum Outcome {
9:     Delivered(Receipt),
10:     Retry(u64),
11: }
12: /// Submit a request, returning it to the caller on expiry for later retry.
13: pub async fn deliver(transport: &impl Transport, request: u64, deadline: Duration) -> Outcome {
14:     match tokio::time::timeout(deadline, transport.send(request)).await {
15:         Ok(receipt) => Outcome::Delivered(receipt),
16:         Err(_) => Outcome::Retry(request),
17:     }
18: }

